Get the data

#this is my key, stored locally. You can get your own, it's free
key &lt;- read_lines("apikey.txt")

#moon data
moons &lt;- GET("https://api.le-systeme-solaire.net/rest/bodies/", 
           add_headers(Authorization = paste("Bearer", key)),
           query = list(`filter[]` = "bodyType,eq,Moon")) |&gt; 
  content()

#planet data
planets &lt;- GET("https://api.le-systeme-solaire.net/rest/bodies/", 
               add_headers(Authorization = paste("Bearer", key)),
               query = list(`filter[]` = "bodyType,eq,Planet")) |&gt; 
  content()

useful &lt;- c("id", "englishName", "semimajorAxis", "mass", "sideralOrbit", "aroundPlanet")

#wrangle this ugly list into a nice tibble
planets &lt;- planets$bodies |&gt; 
  map(\(x) x |&gt; 
        #some elements are null, some are lists of length 2
        #as_tibble_row complains, that's why the gymnastics
        discard(is_null) |&gt; 
        enframe() |&gt; 
        pivot_wider()) |&gt; 
  #bind the planet rows into a tibble
  bind_rows() |&gt; 
  #keep only what's necessary
  select(any_of(useful)) |&gt; 
  #mass is in scientific notation across two fields
  mutate(mass = map_dbl(mass, \(x) x$massValue * 10^x$massExponent)) |&gt;
  #undo the list-cols created by enframe() |&gt; pivot_wider()
  mutate(across(everything(), unlist))

#same as above, but for moons
moons &lt;- moons$bodies |&gt; 
  map(\(x) x |&gt; 
        discard(is_null) |&gt; 
        enframe() |&gt; 
        pivot_wider()) |&gt; 
  bind_rows() |&gt; 
  select(id, englishName, semimajorAxis, mass, sideralOrbit, aroundPlanet) |&gt; 
  #some moons have missing mass
  drop_na() |&gt; 
  mutate(mass = map_dbl(mass, \(x) x$massValue * 10^x$massExponent),
         #just need the id of the planet
         aroundPlanet = map(aroundPlanet, 1)) |&gt; 
  mutate(across(everything(), unlist)) |&gt; 
  #there are some bogus entries
  filter(sideralOrbit &gt; 0)

#join planets to moons
data &lt;- moons |&gt; 
  inner_join(planets |&gt; select(id, mass),
             by = join_by(aroundPlanet == id),
             suffix = c("_s", "_p")) |&gt; 
  mutate(
    #only the sum of masses is identified in the equation
    M = mass_s + mass_p,
    #convert semi-major axis to meters
    a = semimajorAxis * 1000,
    #convert sideral orbit to seconds
    #to be fancy, use a more accurate sideral day
    T = sideralOrbit * 23.9344696 * 3600,
    #remind the value of pi to the model
    pi = pi)

data

